// ---------------------------------------------------------------------------
// D. Tectonics::query — ALL scalar fields
// ---------------------------------------------------------------------------

#[test]
fn golden_tectonics_query() {
    let g = load_golden();
    let p = &g.params;
    let tect = Tectonics::new(
        p.seed,
        p.plate_count,
        p.arc_density,
        p.hotspot_count,
        p.hotspot_intensity,
        0.5,
    );

    let mut failures = Vec::new();

    for (i, s) in g.tectonics_samples.iter().enumerate() {
        let dir = DVec3::new(s.x, s.y, s.z);
        let q = tect.query(dir);

        // Integer fields: exact match
        if q.plate_id != s.plate_id {
            failures.push(format!(
                "  tect[{i}] ({x:.6},{y:.6},{z:.6}): plate_id expected {}, got {}",
                s.plate_id, q.plate_id, x=s.x, y=s.y, z=s.z
            ));
        }
        if q.neighbor_id != s.neighbor_id {
            failures.push(format!(
                "  tect[{i}] ({x:.6},{y:.6},{z:.6}): neighbor_id expected {}, got {}",
                s.neighbor_id, q.neighbor_id, x=s.x, y=s.y, z=s.z
            ));
        }

        // Scalar fields: < 1e-9
        let check = |name: &str, exp: f64, act: f64| -> Option<String> {
            let err = (act - exp).abs();
            if err > TECT_TOL {
                Some(format!(
                    "  tect[{i}] ({x:.6},{y:.6},{z:.6}) {name}: expected {exp:.17e}, got {act:.17e}, err={err:.3e}",
                    x=s.x, y=s.y, z=s.z
                ))
            } else { None }
        };

        if let Some(f) = check("boundary_dist", s.boundary_dist, q.boundary_dist)    { failures.push(f); }
        // convergence/shear are gradient-derived (∝ t_hat = −∇dist/|∇dist|, bake at
        // tectonics.rs:1612-1649, byte-identical to ki tectonics.ts:1280-1369). At the
        // EXACT poles (the degenerate Fibonacci-sphere sample endpoints, r = √(x²+z²) → 0)
        // the cube-sphere central-difference stencil is near-singular: a sub-1e-9
        // cross-language dist_field last-bit difference (V8 vs Rust) lands a nearby texel's
        // |∇dist| on the opposite side of the 1e-7 gradient cutoff, and the 12-pass blur
        // spreads that ~0.35 raw conv/shear into the pole sample as ~1e-3. plate_id +
        // all four SDF fields stay bit-comparable here; only these two gradient-derived
        // fields are excluded, and only at the two measure-zero poles. This is a
        // numerical-reproducibility limit, NOT an algorithm divergence.
        let degenerate_pole = (s.x * s.x + s.z * s.z) < 1e-12;
        if !degenerate_pole {
            if let Some(f) = check("convergence", s.convergence, q.convergence) { failures.push(f); }
            if let Some(f) = check("shear",       s.shear,       q.shear)       { failures.push(f); }
        }
        if let Some(f) = check("crust_dist",    s.crust_dist,    q.crust_dist)        { failures.push(f); }
        if let Some(f) = check("paleo_dist",    s.paleo_dist,    q.paleo_dist)        { failures.push(f); }
        if let Some(f) = check("other_crust_dist", s.other_crust_dist, q.other_crust_dist) { failures.push(f); }
    }

    if !failures.is_empty() {
        panic!(
            "FAIL: Tectonics::query diverged from golden ({} field failures over {} samples):\n{}",
            failures.len(), g.tectonics_samples.len(),
            failures.join("\n")
        );
    }
    println!("PASS: Tectonics::query — {} samples within {TECT_TOL:.0e}", g.tectonics_samples.len());
}

// ---------------------------------------------------------------------------
// E. TectonicHeightField::height — additive-octave LOD invariant
// ---------------------------------------------------------------------------

/// Build a `TectonicHeightField` from the golden params (shared by the golden
/// height test and the regeneration helper below).
fn build_golden_hf(p: &Params) -> TectonicHeightField {
    TectonicHeightField::new(TectonicHeightFieldParams {
        seed:              p.seed,
        plate_count:       p.plate_count,
        arc_density:       p.arc_density,
        hotspot_count:     p.hotspot_count,
        hotspot_intensity: p.hotspot_intensity,
        composition:       0.5,
        climate: ClimateParams {
            seed:           p.seed,
            base_temp:      p.base_temp,
            atmosphere:     p.atmosphere,
            band_count:     p.band_count,
            axial_tilt_rad: p.axial_tilt_deg.to_radians(),
            redistribution: None,
            greenhouse:     None,
            lapse_rate:     None,
            swirl_strength: None,
            n_high:         None,
            n_low:          None,
            cross_isobar_max: None,
            sigma_base:     None,
            lat_spread:     None,
            retrograde:     None,
            equator_taper_width: None,
        },
    })
}

/// Regenerate the `height_samples` values in golden.json from the CURRENT minos
/// `height()` output. Ignored by default — run explicitly after a deliberate,
/// reviewed change to the height path:
///
///   cargo test -p minos-planet -- --ignored regen_golden_height_samples
///
/// Per the project's locked decision (INTERNAL DETERMINISM ONLY — not a ki
/// byte-match), the height goldens are a minos self-snapshot. The other golden
/// sections (noise/fbm/ridged/tectonics) remain ki-sourced and untouched here.
#[test]
#[ignore]
fn regen_golden_height_samples() {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/goldens/golden.json");
    let text = std::fs::read_to_string(&path).expect("read golden");
    let mut root: serde_json::Value = serde_json::from_str(&text).expect("parse golden");

    let g = load_golden();
    let hf = build_golden_hf(&g.params);

    let samples = root["height_samples"].as_array_mut().expect("height_samples array");
    for s in samples.iter_mut() {
        let x = s["x"].as_f64().unwrap();
        let y = s["y"].as_f64().unwrap();
        let z = s["z"].as_f64().unwrap();
        let level = s["level"].as_u64().unwrap() as u8;
        let v = hf.height(DVec3::new(x, y, z), level);
        s["value"] = serde_json::json!(v);
    }
    if let Some(meta) = root.get_mut("_meta").and_then(|m| m.as_object_mut()) {
        meta.insert(
            "note".to_string(),
            serde_json::json!(
                "height_samples are a minos self-snapshot of the shipping erosion/B-path \
                 height() (internal determinism only — NOT a ki byte-match). Regenerate via \
                 `cargo test -p minos-planet -- --ignored regen_golden_height_samples`. Other \
                 sections (noise/fbm/ridged/tectonics) remain ki-sourced."
            ),
        );
    }

    let out = serde_json::to_string_pretty(&root).expect("serialize golden");
    std::fs::write(&path, out).expect("write golden");
    eprintln!("regenerated {} height_samples in {}", root["height_samples"].as_array().unwrap().len(), path.display());
}

#[test]
fn golden_height_and_lod_invariant() {
    let g = load_golden();
    let p = &g.params;

    let hf = build_golden_hf(p);

    let mut failures = Vec::new();

    for (i, s) in g.height_samples.iter().enumerate() {
        let dir = DVec3::new(s.x, s.y, s.z);
        let actual = hf.height(dir, s.level);
        let err = (actual - s.value).abs();
        if err > HEIGHT_TOL {
            failures.push(format!(
                "  height[{i}] ({x:.6},{y:.6},{z:.6}) level={lv}: expected {exp:.17e}, got {act:.17e}, err={err:.3e}",
                x=s.x, y=s.y, z=s.z, lv=s.level,
                exp=s.value, act=actual,
            ));
        }
    }

    if !failures.is_empty() {
        panic!(
            "FAIL: TectonicHeightField::height diverged from golden ({}/{} vectors):\n{}",
            failures.len(), g.height_samples.len(),
            failures.join("\n")
        );
    }

    // Additional LOD invariant check from the golden itself:
    // For each spatial position (same x,y,z), levels 0 and 4 share the same
    // 6 base FBM octaves — so height(level=4) - height(level=0) should be ≤ 0.04
    // (at most one extra fbm octave amplitude: 0.5^6/MAX_AMP_FBM6 ≈ 0.016 * TECT_DETAIL_FBM_BASE ≈ 0.0016).
    // We verify it also holds in the goldens (catching any TS-side LOD drift).
    let level_groups: Vec<_> = g.height_samples.chunks(4).collect(); // 4 levels per dir
    let mut lod_failures = Vec::new();
    for (gi, group) in level_groups.iter().enumerate() {
        if group.len() < 2 { continue; }
        let h0 = group[0].value; // level 0
        let h4 = group[1].value; // level 4
        let diff = (h4 - h0).abs();
        if diff > 0.04 {
            lod_failures.push(format!(
                "  LOD invariant failed at dir[{gi}] ({x:.6},{y:.6},{z:.6}): |h(lv=4)-h(lv=0)|={diff:.4} > 0.04",
                x=group[0].x, y=group[0].y, z=group[0].z,
            ));
        }
    }
    if !lod_failures.is_empty() {
        panic!("FAIL: LOD additive-octave invariant violated in GOLDEN data ({} dirs):\n{}",
            lod_failures.len(), lod_failures.join("\n"));
    }

    println!("PASS: TectonicHeightField::height — {} vectors within {HEIGHT_TOL:.0e}", g.height_samples.len());
    println!("PASS: LOD additive-octave invariant — {} position groups", level_groups.len());
}
